begin;
\ir bag-reception-fixture.inc
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000000641','readiness-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000000642','readiness-bot@example.test',now()),
 ('f0000000-0000-4000-8000-000000000643','readiness-outsider@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000641","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Readiness test','catalog-readiness',gen_random_uuid())::text,true);
select set_config('test.merchant',gen_random_uuid()::text,true);
select enable_zettle_pull(current_setting('test.tenant')::uuid,current_setting('test.merchant')::uuid);
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.tenant')::uuid)->'policy')||'{"vatModeConsignmentPrivate":"consignment_margin"}');
select set_config('test.config',gen_random_uuid()::text,true);
select publish_zettle_catalog_config(current_setting('test.tenant')::uuid,current_setting('test.config')::uuid,null,'{"consignment_margin":0}');
select set_config('test.purchase',register_purchase(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic purchase',15000,'Test receipt',false)::text,true);
select set_config('test.own',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.own')::uuid,'purchase',current_setting('test.purchase')::uuid,null,25000);
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','readiness-seller@example.test','')::text,true);
select set_config('test.agreement',publish_seller_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'Synthetic terms','Only a test','en',false)::text,true);
select record_agreement_evidence(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.agreement')::uuid,'Test evidence');
select set_config('test.bag',receive_bag_with_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,'',current_setting('test.agreement')::uuid)::text,true);
select set_config('test.draft',gen_random_uuid()::text,true);
select pg_temp.prepare_bag_reception(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag')::uuid,current_setting('test.draft')::uuid,0,'Synthetic jacket','Jackets','Good');
select set_config('test.consigned',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.consigned')::uuid,'reception_review',current_setting('test.draft')::uuid,1,25000);
create temp view own_status as select paypal_item_status(current_setting('test.tenant')::uuid,array[current_setting('test.own')::uuid])->0 s;
select is((select s->>'status' from own_status),'attention','missing store-owned VAT is visible before any export');
select is((select s->>'errorCode' from own_status),'VAT_MODE_NOT_SET','missing mode has an actionable safe code');
select is((select s->>'canExport' from own_status),'false','missing mode prevents export eligibility');
select is((select s->>'productStatus' from own_status),null::text,'readiness invents no provider outcome');
select is(paypal_item_status(current_setting('test.tenant')::uuid,array[current_setting('test.consigned')::uuid])->0->>'canExport','true','valid consignment remains eligible');
select is((items_search_page(current_setting('test.tenant')::uuid,'{"paypal":"attention"}','title','asc',25,0)->>'total')::integer,1,'blocked item discoverable through existing status filter');
select throws_like($$select prepare_zettle_product(current_setting('test.tenant')::uuid,current_setting('test.own')::uuid)$$,'%VAT_MODE_NOT_SET%','direct export retains financial validation');
select set_config('test.binding',gen_random_uuid()::text,true);
select save_catalog_automation(current_setting('test.tenant')::uuid,current_setting('test.binding')::uuid,'paypal',current_setting('test.merchant'),null,true,'readiness-bot@example.test');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000642","role":"authenticated"}';
select accept_automation_grants();
select set_config('test.job',gen_random_uuid()::text,true);
select is(claim_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'paypal')->>'itemId',current_setting('test.consigned'),'blocked earlier item does not starve valid consignment');
select finish_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'held');
select is(claim_catalog_export(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal'),null::jsonb,'blocked item does not create a failing job');
select is(claim_catalog_export(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal'),null::jsonb,'repeated scan does not retry missing configuration');
select throws_like($$select prepare_zettle_product(current_setting('test.tenant')::uuid,current_setting('test.own')::uuid)$$,'%FORBIDDEN%','blocked item has no export lease');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000641","role":"authenticated"}';
select is((select count(*) from catalog_export_jobs where item_id=current_setting('test.own')::uuid),0::bigint,'no hidden job for blocked item');
select is((select count(*) from zettle_product_exports where item_id=current_setting('test.own')::uuid),0::bigint,'no product snapshot written');
-- Use the established margin fallback: this purchase lacks margin attestation.
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),(current_store_policy(current_setting('test.tenant')::uuid)->>'id')::uuid,(current_store_policy(current_setting('test.tenant')::uuid)->'policy')||'{"vatModeStoreOwned":"store_margin"}');
select is((select s->>'errorCode' from own_status),'ZETTLE_VAT_MAPPING_REQUIRED','configured mode still requires its effective mapping');
select is((select s->>'canExport' from own_status),'false','missing mapping stays blocked');
select publish_zettle_catalog_config(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.config')::uuid,'{"consignment_margin":0,"store_margin":0}');
select is((select s->>'errorCode' from own_status),'ZETTLE_VAT_MAPPING_REQUIRED','readiness honors actual store_full fallback, not just configured store_margin');
select publish_zettle_catalog_config(current_setting('test.tenant')::uuid,gen_random_uuid(),(select id from zettle_catalog_configs where tenant_id=current_setting('test.tenant')::uuid order by revision desc limit 1),'{"consignment_margin":0,"store_margin":0,"store_full":25}');
select is((select s->>'status' from own_status),'not_sent','correcting configuration restores original unsent state');
select is((select s->>'errorCode' from own_status),null::text,'resolved configuration clears readiness code');
select is((select s->>'canExport' from own_status),'true','corrected configuration automatically restores eligibility');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000642","role":"authenticated"}';
select set_config('test.fixed_job',gen_random_uuid()::text,true);
select is(claim_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.fixed_job')::uuid,'paypal')->>'itemId',current_setting('test.own'),'new claim allowed only after configuration correction');
select is(claim_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.fixed_job')::uuid,'paypal'),null::jsonb,'lost response still cannot execute twice');
select lives_ok($$select prepare_zettle_product(current_setting('test.tenant')::uuid,current_setting('test.own')::uuid)$$,'same sale facts permit the actual product preparation');
select finish_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.fixed_job')::uuid,'held');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000641","role":"authenticated"}';
select is((select count(*) from catalog_export_outcomes where tenant_id=current_setting('test.tenant')::uuid and outcome='held'),2::bigint,'earlier job history is preserved');
select record_sale(current_setting('test.tenant')::uuid,gen_random_uuid(),'manual','readiness-sale',now(),'SEK',jsonb_build_array(jsonb_build_object('itemId',current_setting('test.own'),'priceOre',25000)));
select is((select s->>'status' from own_status),'inactive','sold items are not revalidated as new sales');
select is((select s->>'canExport' from own_status),'false','sold items stay ineligible');
select save_catalog_automation(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal',current_setting('test.merchant'),current_setting('test.binding')::uuid,false,null);
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000642","role":"authenticated"}';
select throws_like($$select claim_catalog_export(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal')$$,'%FORBIDDEN%','revoked automation remains forbidden');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000643","role":"authenticated"}';
select throws_like($$select paypal_item_status(current_setting('test.tenant')::uuid,array[current_setting('test.own')::uuid])$$,'%FORBIDDEN%','cross-tenant status remains forbidden');
select throws_like($$select komisio_private.paypal_item_snapshot(current_setting('test.tenant')::uuid,current_setting('test.own')::uuid)$$,'%permission denied%','private snapshot not directly accessible');
select * from finish();
rollback;
